pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Recibe REFUND_PROCESSED y PROJECT_FAILED", function () {
    const json = pm.response.json();
    const refund = json.find(n => n.type === "REFUND_PROCESSED");
    const failed = json.find(n => n.type === "PROJECT_FAILED");

    pm.expect(refund, "REFUND_PROCESSED").to.not.be.undefined;
    pm.expect(failed, "PROJECT_FAILED").to.not.be.undefined;
});

