pm.test("El creador recibió PROJECT_FAILED", function () {
    const json = pm.response.json();
    const n = json.find(x => x.type === "PROJECT_FAILED");

    pm.expect(n, "notificación PROJECT_FAILED").to.not.be.undefined;
    pm.expect(n.isRead).to.eql(false);
});
